//! JSON schema for the scene metadata file (`<glb>.scene.json`).
//!
//! Generated by `scripts/avatars/extract_scene_metadata.py` from the GLB; can be
//! hand-edited afterwards. Loaded once at startup as a Bevy resource.

use bevy::prelude::*;
use serde::{Deserialize, Serialize};

#[derive(Resource, Debug, Clone, Serialize, Deserialize)]
pub struct SceneMetadata {
    #[serde(default = "default_schema_version")]
    pub schema_version: u32,
    #[serde(default)]
    pub floor_y: f32,
    #[serde(default = "default_avatar_radius")]
    pub avatar_radius: f32,
    #[serde(default)]
    pub objects: Vec<SceneObject>,
    #[serde(default)]
    pub spawn_points: Vec<SpawnPoint>,
}

fn default_schema_version() -> u32 {
    1
}
fn default_avatar_radius() -> f32 {
    0.30
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SceneObject {
    pub id: String,
    #[serde(rename = "type")]
    pub object_type: String,
    pub transform: ObjectTransform,
    pub world_aabb: Aabb,
    pub footprint: Footprint,
    #[serde(default)]
    pub anchors: Option<Anchors>,
    #[serde(default)]
    pub sit_anchor_source: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ObjectTransform {
    pub position: [f32; 3],
    #[serde(default)]
    pub yaw_deg: f32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Aabb {
    pub min: [f32; 3],
    pub max: [f32; 3],
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "shape", rename_all = "lowercase")]
pub enum Footprint {
    Circle {
        center_xz: [f32; 2],
        radius: f32,
    },
    Rect {
        center_xz: [f32; 2],
        size: [f32; 2],
        #[serde(default)]
        yaw_deg: f32,
    },
}

impl Footprint {
    pub fn center_xz(&self) -> Vec2 {
        match self {
            Footprint::Circle { center_xz, .. } | Footprint::Rect { center_xz, .. } => {
                Vec2::new(center_xz[0], center_xz[1])
            }
        }
    }

    /// Inflated polygon in CCW order (XZ plane). Used by the visibility
    /// graph as obstacle vertices. Inflation = avatar_radius + small margin.
    /// Ground distance from `p` to the footprint (0 inside), using the same
    /// square-cornered geometry as `inflated_polygon` (L-inf for rectangles).
    pub fn distance(&self, p: Vec2) -> f32 {
        match self {
            Footprint::Circle { center_xz, radius } => {
                ((p - Vec2::new(center_xz[0], center_xz[1])).length() - radius).max(0.0)
            }
            Footprint::Rect { center_xz, size, yaw_deg } => {
                let d = p - Vec2::new(center_xz[0], center_xz[1]);
                let (sin, cos) = yaw_deg.to_radians().sin_cos();
                // Inverse of inflated_polygon's local -> world rotation.
                let local = Vec2::new(cos * d.x + sin * d.y, -sin * d.x + cos * d.y);
                (local.x.abs() - size[0] / 2.0).max(local.y.abs() - size[1] / 2.0).max(0.0)
            }
        }
    }

    pub fn inflated_polygon(&self, inflation: f32) -> Vec<Vec2> {
        match self {
            Footprint::Circle { center_xz, radius } => {
                // 8-gon approximation
                let r = (*radius + inflation) / (std::f32::consts::PI / 8.0).cos();
                let c = Vec2::new(center_xz[0], center_xz[1]);
                (0..8)
                    .map(|i| {
                        let a = std::f32::consts::TAU * (i as f32) / 8.0;
                        c + Vec2::new(a.cos(), a.sin()) * r
                    })
                    .collect()
            }
            Footprint::Rect {
                center_xz,
                size,
                yaw_deg,
            } => {
                let c = Vec2::new(center_xz[0], center_xz[1]);
                let hx = size[0] / 2.0 + inflation;
                let hz = size[1] / 2.0 + inflation;
                let yaw = yaw_deg.to_radians();
                let cos = yaw.cos();
                let sin = yaw.sin();
                let rotate = |dx: f32, dz: f32| Vec2::new(cos * dx - sin * dz, sin * dx + cos * dz);
                vec![
                    c + rotate(-hx, -hz),
                    c + rotate(hx, -hz),
                    c + rotate(hx, hz),
                    c + rotate(-hx, hz),
                ]
            }
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct Anchors {
    /// World-space pelvis position when seated. Snapped from the FBX
    /// animation pelvis at the script's sample time when available.
    pub seat_pelvis: Option<[f32; 3]>,
    /// World-space floor position where the avatar stands before sitting,
    /// in front of the chair in its facing direction.
    pub stand_to_sit: Option<[f32; 3]>,
    /// Direction the avatar faces when seated (yaw degrees, +Z = 0°).
    #[serde(default)]
    pub facing_yaw_deg: Option<f32>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SpawnPoint {
    pub id: String,
    pub position: [f32; 3],
}

impl SceneMetadata {
    pub fn object(&self, id: &str) -> Option<&SceneObject> {
        self.objects.iter().find(|o| o.id == id)
    }

    pub fn spawn_point(&self, id: &str) -> Option<&SpawnPoint> {
        self.spawn_points.iter().find(|s| s.id == id)
    }

    /// Compact summary suitable for an LLM system prompt — one line per object
    /// with id / type / position / size / interaction hints.
    pub fn llm_context(&self) -> String {
        use std::fmt::Write;
        let mut out = String::new();
        let _ = writeln!(out, "Scene objects (id | type | world position | size):");
        for o in &self.objects {
            let p = o.transform.position;
            let size = match &o.footprint {
                Footprint::Circle { radius, .. } => format!("circle r={radius:.2}m"),
                Footprint::Rect { size, .. } => format!("rect {:.2}×{:.2}m", size[0], size[1]),
            };
            let _ = write!(
                out,
                "  • {id} | {ty} | ({px:+.2}, {py:+.2}, {pz:+.2}) | {size}",
                id = o.id,
                ty = o.object_type,
                px = p[0],
                py = p[1],
                pz = p[2],
            );
            if let Some(a) = &o.anchors {
                if let Some(seat) = a.seat_pelvis {
                    let _ = write!(
                        out,
                        " | sit_pelvis=({:+.2}, {:+.2}, {:+.2})",
                        seat[0], seat[1], seat[2]
                    );
                }
                if let Some(face) = a.facing_yaw_deg {
                    let _ = write!(out, " | facing={face:+.0}°");
                }
            }
            let _ = writeln!(out);
        }
        if !self.spawn_points.is_empty() {
            let _ = writeln!(out, "Spawn points (id | world position):");
            for s in &self.spawn_points {
                let p = s.position;
                let _ = writeln!(
                    out,
                    "  • {} | ({:+.2}, {:+.2}, {:+.2})",
                    s.id, p[0], p[1], p[2]
                );
            }
        }
        out
    }
}
